// MIFARE Classic 1K functional memory/access model, not a Crypto1 RF emulator.
export const crcA=bytes=>{let crc=0x6363;for(let v of bytes){v^=crc&255;v^=(v<<4)&255;crc=((crc>>8)^(v<<8)^(v<<3)^(v>>4))&65535;}return[crc&255,crc>>8];};
const DATA=[['AB','AB','AB','AB'],['AB','','','AB'],['AB','','',''],['B','B','',''],['AB','B','',''],['B','','',''],['AB','B','B','AB'],['','','','']];
const TRAILER=[['A','A','','A','A'],['A','A','A','A','A'],['','A','','A',''],['B','AB','B','','B'],['B','AB','','','B'],['','AB','B','',''],['','AB','','',''],['','AB','','','']];
export class ClassicCard {
 constructor(){this.cards=new Map();this.setEnvironment({});}
 setEnvironment(p){const id=(p.uid??0xdeadbeef)>>>0;if(id!==this.id){this.id=id;if(!this.cards.has(id)){const m=new Uint8Array(1024);for(let s=0;s<16;s++){m.fill(255,s*64+48,s*64+54);m.set([255,7,128,105],s*64+54);m.fill(255,s*64+58,s*64+64);}m.set(this.uid());m[4]=this.uid().reduce((a,b)=>a^b,0);this.cards.set(id,m);}this.memory=this.cards.get(id);this.reset();}this.present=!!(p.present??1);if(!this.present)this.reset();}
 uid(){return[this.id>>>24,this.id>>>16&255,this.id>>>8&255,this.id&255];}
 reset(){this.auth=null;this.selected=false;this.halted=false;this.transferValue=null;}
 acl(block){if(!Number.isInteger(block)||block<0||block>=64)return null;const a=(block>>2)*64+54,m=this.memory,c1=m[a+1]>>4,c2=m[a+2]&15,c3=m[a+2]>>4;if((c1^(m[a]&15))!==15||(c2^(m[a]>>4))!==15||(c3^(m[a+1]&15))!==15)return null;const i=block&3;return((c1>>i&1)<<2)|((c2>>i&1)<<1)|(c3>>i&1);}
 authenticate(op,block,key,uid){this.auth=null;if(!this.present||this.halted||!this.selected||![0x60,0x61].includes(op)||block>=64||block<0||!uid?.every((v,i)=>v===this.uid()[i])||uid.length!==4||key.length!==6)return false;const sector=block>>2,a=sector*64+48,kind=op===0x60?'A':'B',acl=this.acl(sector*4+3);if(acl===null||kind==='B'&&TRAILER[acl][3])return false;const at=a+(kind==='A'?0:10);if(!key.every((v,i)=>v===this.memory[at+i]))return false;this.auth={sector,kind};return true;}
 permission(block,operation){const acl=this.acl(block),auth=this.auth;if(!this.present||!auth||auth.sector!==(block>>2)||acl===null)return false;return DATA[acl][operation].includes(auth.kind);}
 read(block){if(block<0||block>=64||!this.auth||this.auth.sector!==(block>>2))return null;const a=block*16;if((block&3)!==3)return this.permission(block,0)?Array.from(this.memory.slice(a,a+16)):null;const acl=this.acl(block);if(acl===null||!TRAILER[acl][1].includes(this.auth.kind))return null;const b=Array.from(this.memory.slice(a,a+16));b.fill(0,0,6);if(!TRAILER[acl][3].includes(this.auth.kind))b.fill(0,10,16);return b;}
 write(block,data){if(block<=0||block>=64||data.length!==16||!this.auth||this.auth.sector!==(block>>2))return false;const a=block*16;if((block&3)===3){const acl=this.acl(block);if(acl===null)return false;const access=TRAILER[acl],key=this.auth.kind;for(const[start,end,index]of [[0,6,0],[6,10,2],[10,16,4]])if(data.slice(start,end).some((v,i)=>v!==this.memory[a+start+i])&&!access[index].includes(key))return false;}else if(!this.permission(block,1))return false;this.memory.set(data,a);return true;}
 value(block){const b=this.read(block);if(!b)return null;for(let i=0;i<4;i++)if(b[i]!==b[i+8]||(b[i]^b[i+4])!==255)return null;if(b[12]!==b[14]||b[13]!==b[15]||(b[12]^b[13])!==255)return null;return(b[0]|b[1]<<8|b[2]<<16|b[3]<<24)|0;}
 adjust(op,block,operand){const kind=op===0xc1?2:3,n=this.value(block);if(n===null||!this.permission(block,kind))return false;this.transferValue=op===0xc2?n:(op===0xc1?n+operand:n-operand)|0;return true;}
 transfer(block){if(block<=0||block>=64||(block&3)===3||this.transferValue===null||!this.permission(block,3))return false;const n=this.transferValue,b=Array.from({length:4},(_,i)=>n>>>(i*8)&255);this.memory.set([...b,...b.map(v=>v^255),...b,block,block^255,block,block^255],block*16);return true;}
}
